style.css:
@-moz-document domain("docs.google.com") {
/* Background Color */
    body {
        background-color: #F2E6FF !important;
    }

    /* Header background and text */
    .docs-title-input, .docs-title-outer {
        background-color: #E0B3FF !important;
        color: #5A3D85 !important;
    }

    /* Toolbar Background Color */
    .kix-appview-editor {
        background-color: #F2E6FF !important;
    }

    /* Change button background and text color */
    .goog-toolbar-button {
        background-color: #D1A6FF !important;
        color: #4B0082 !important;
    }

    /* Links */
    a {
        color: #7A5CFF !important;
    }

    /* Table Background */
    .kix-table-container {
        background-color: #F8F0FF !important;
    }

    /* Change text color in the document */
    .kix-wordhtmlgenerator-word-node {
        color: #5A3D85 !important;
    }

    /* Modify cursor on hover */
    .goog-toolbar-button:hover {
        background-color: #B39DDB !important;
    }

    /* Sidebar and menu */
    .docs-iframe-menu, .docs-canvas-content {
        background-color: #F2E6FF !important;
    }

    /* Footer color */
    .docs-footer {
        background-color: #E0B3FF !important;
    }

    /* Other elements like comments */
    .docs-comment-tooltip {
        background-color: #D1A6FF !important;
    }
}
